  "staffm.title": "أعضاء الموظفين",
  "staffm.sub": "هنا تضيف موظفي جامعتك. يرتبط الموظف بجامعتك — ولا تُنشأ له جامعة مستقلة. سيرى فقط الأقسام التي تفتحها له؛ وستبقى الرواتب والنسخ الاحتياطي والسجل العام وإضافة المستخدمين لك وحدك دائمًا. لا يمكن جعل Gmail لديه جامعة خاصة به موظفًا.",
