  "backup.title": "النسخ الاحتياطي",
  "backup.sub": "بالضغط على الزر أدناه سيُنزَّل كل بيانات جامعتك في ملف (JSON) — بما فيها السجلات النشطة والملغاة. ستصلك بياناتك أنت فقط، ولن تصلك بيانات أي مستخدم آخر أبدًا. هذا الملف نسختك الخاصة — احفظه في مكان آمن. الخطة المجانية من Supabase لا تُنشئ نسخًا احتياطية تلقائية، لذا نزّل نسخة احتياطية جديدة مرة كل شهر واحفظها في مكانين.",
